<?php
include 'auth_check.php';require_once __DIR__.'/bootstrap.php';
$offers=(new App\Domain\Offer\OfferRepository(app_database()))->all();$clients=(new App\Domain\Client\ClientRepository(app_database()))->all();$statusLabels=['en_cours'=>'En cours','remporte'=>'Remporté','termine'=>'Terminé','non_remporte'=>'Non remporté'];$offerError=(string)($_SESSION['offer_error']??'');unset($_SESSION['offer_error']);
function oh(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function offerDays(?string $deadline):?int{if(!$deadline)return null;return (int)(new DateTimeImmutable('today'))->diff(new DateTimeImmutable($deadline))->format('%r%a');}
