<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Appels d’Offre · FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"><style>
.offers-hero{display:flex;align-items:center;justify-content:space-between;gap:25px;padding:32px;color:#fff;background:linear-gradient(120deg,var(--brand-primary),var(--brand-primary-soft));border-radius:26px;box-shadow:0 18px 48px #22254b29}.offers-hero h1{margin:0;color:#fff!important}.offers-hero p{margin:9px 0 0;color:#ffffffb8}.offers-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(370px,1fr));gap:20px;margin-top:25px}.offer-card{position:relative;overflow:hidden;background:#fff;border:1px solid var(--brand-border);border-radius:22px;box-shadow:0 12px 34px #22254b10;transition:.22s}.offer-card:hover{transform:translateY(-5px);box-shadow:0 22px 52px #22254b20}.offer-card:before{position:absolute;inset:0 auto 0 0;width:5px;content:"";background:#e2a900}.offer-card.remporte:before{background:#15935b}.offer-card.non_remporte:before{background:#d64b57}.offer-card.termine:before{background:#6b6f83}.offer-head{display:flex;align-items:center;gap:15px;padding:20px 21px 14px}.offer-logo{display:grid;width:78px;height:78px;flex:0 0 78px;place-items:center;overflow:hidden;color:var(--brand-primary);background:#f0f1f5;border:1px solid #e0e1e8;border-radius:19px;font:900 1.3rem var(--brand-font-heading)}.offer-logo img{width:100%;height:100%;padding:7px;object-fit:contain;background:#fff}.offer-client{color:#838697;font-size:.69rem;font-weight:850;letter-spacing:.06em;text-transform:uppercase}.offer-head h2{display:-webkit-box;overflow:hidden;margin:4px 0 7px;color:var(--brand-primary);font:850 1.08rem/1.25 var(--brand-font-heading);-webkit-box-orient:vertical;-webkit-line-clamp:2}.offer-number{color:#737688;font-size:.73rem}.offer-status{margin-left:auto;align-self:flex-start;padding:6px 9px;border-radius:99px;background:#fff0bd;color:#805c00;font-size:.65rem;font-weight:900;white-space:nowrap}.offer-status.remporte{color:#147343;background:#dbf5e7}.offer-status.non_remporte{color:#a52e39;background:#fae8ea}.offer-status.termine{color:#5f6273;background:#ececf1}.offer-main{padding:0 21px 19px}.offer-amount{display:flex;align-items:end;justify-content:space-between;gap:10px;padding:17px;color:#fff;background:linear-gradient(125deg,#292c57,#3c4178);border-radius:15px}.offer-amount small,.offer-amount strong{display:block}.offer-amount small{color:#ffffffa9;font-size:.66rem;text-transform:uppercase}.offer-amount strong{margin-top:4px;font-size:1.35rem}.deadline{display:flex;align-items:center;gap:9px;padding:8px 11px;color:#22254b;background:#fabd02;border-radius:10px;font-size:.72rem;font-weight:900}.deadline.late{color:#fff;background:#c63f4c}.offer-details{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:14px 0}.offer-detail{padding:10px;background:#f6f6f9;border-radius:11px}.offer-detail small,.offer-detail strong{display:block}.offer-detail small{color:#8b8e9f;font-size:.61rem;text-transform:uppercase}.offer-detail strong{margin-top:3px;color:#3c3e52;font-size:.76rem}.offer-actions{display:flex;gap:8px;flex-wrap:wrap;padding-top:13px;border-top:1px solid var(--brand-border)}.offer-actions a{display:inline-flex;align-items:center;gap:6px}.offer-used{display:flex;align-items:center;gap:7px;margin-bottom:12px;padding:9px 11px;color:#147343;background:#e4f5eb;border-radius:10px;font-size:.72rem;font-weight:800}@media(max-width:600px){.offers-grid{grid-template-columns:1fr}.offers-hero{align-items:flex-start;flex-direction:column}.offer-head{align-items:flex-start}.offer-logo{width:64px;height:64px;flex-basis:64px}}
</style></head><body class="module-page"><?php include __DIR__.'/partials/navbar.php';?><main class="container"><section class="offers-hero"><div><div class="small text-warning fw-bold">PIPELINE COMMERCIAL · ÉTAPE 1</div><h1>Appels d’Offre</h1><p>Identifiez en un regard le client, l’enjeu financier et l’échéance de réponse.</p></div><button class="btn btn-warning" data-bs-toggle="modal" data-bs-target="#addOfferModal"><i class="fa-solid fa-plus me-2"></i>Nouvel appel d’offre</button></section><?php if($offerError):?><div class="alert alert-danger mt-3"><?=oh($offerError)?></div><?php endif;?><section class="offers-grid"><?php foreach($offers as $o):$days=offerDays($o['date_limite_reponse']);$initials=mb_strtoupper(mb_substr(trim((string)($o['nom_client']?:'CL')),0,2));?><article class="offer-card <?=oh($o['statut'])?>"><header class="offer-head"><div class="offer-logo"><?php if($o['logo_client']):?><img src="<?=oh($o['logo_client'])?>" alt="Logo <?=oh($o['nom_client'])?>"><?php else:?><?=oh($initials)?><?php endif;?></div><div class="flex-grow-1"><div class="offer-client"><?=oh($o['nom_client']?:'Client non renseigné')?></div><h2><?=oh($o['titre_offre']?:$o['reference_offre'])?></h2><div class="offer-number"><i class="fa-solid fa-hashtag"></i> <?=oh($o['num_offre'])?> · <?=oh($o['reference_offre'])?></div></div><span class="offer-status <?=oh($o['statut'])?>"><?=oh($statusLabels[$o['statut']]??$o['statut'])?></span></header><div class="offer-main"><div class="offer-amount"><div><small>Montant <?=($o['montant_devis']!==null?'du devis':'estimé')?></small><strong><?= $o['montant_affiche']!==null?number_format((float)$o['montant_affiche'],0,',',' ').' FCFA':'À définir'?></strong></div><span class="deadline <?=($days!==null&&$days<0&&$o['statut']==='en_cours')?'late':''?>"><i class="fa-solid fa-hourglass-half"></i><?php if($days===null):?>Sans deadline<?php elseif($days<0):?>Retard <?=abs($days)?> j<?php elseif($days===0):?>Aujourd’hui<?php else:?>J-<?=$days?><?php endif;?></span></div><div class="offer-details"><div class="offer-detail"><small><i class="fa-regular fa-calendar me-1"></i>Reçu le</small><strong><?=oh($o['date_offre'])?></strong></div><div class="offer-detail"><small><i class="fa-solid fa-flag-checkered me-1"></i>Deadline</small><strong><?=oh($o['date_limite_reponse']?:'—')?></strong></div><div class="offer-detail"><small><i class="fa-solid fa-user-tie me-1"></i>Commercial</small><strong><?=oh($o['commercial_dedie'])?></strong></div><div class="offer-detail"><small><i class="fa-solid fa-paperclip me-1"></i>Document</small><strong><?=oh($o['fichier_ao_original']?:'Absent')?></strong></div></div><?php if($o['reserved_quote_id']):?><div class="offer-used"><i class="fa-solid fa-lock"></i>Rattaché au devis #<?=(int)$o['reserved_quote_id']?></div><?php endif;?><div class="offer-actions"><?php if($o['fichier_ao']):?><a class="btn btn-sm btn-outline-secondary" target="_blank" href="<?=oh($o['fichier_ao'])?>"><i class="fa-regular fa-file-lines"></i>Document AO</a><?php endif;?><a class="btn btn-sm btn-outline-primary" href="modifier_offre.php?id=<?=(int)$o['id_offre']?>"><i class="fa-solid fa-pen"></i>Modifier</a><?php if(!$o['reserved_quote_id']&&$o['fichier_ao']):?><a class="btn btn-sm btn-primary" href="generer_devis.php?offre_id=<?=(int)$o['id_offre']?>"><i class="fa-solid fa-file-circle-plus"></i>Créer le devis</a><?php endif;?></div></div></article><?php endforeach;?></section></main>
<div class="modal fade" id="addOfferModal" tabindex="-1"><div class="modal-dialog modal-xl"><div class="modal-content"><div class="modal-header"><h2 class="modal-title h5"><i class="fa-solid fa-briefcase me-2 text-warning"></i>Nouvel appel d’offre</h2><button class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div><div class="modal-body"><form action="request/ajouter_offre.php" method="post" enctype="multipart/form-data"><div class="row g-4"><div class="col-lg-5"><label class="form-label">Document source *</label><input type="file" id="fichier_ao" name="fichier_ao" accept=".pdf,.docx,.jpg,.jpeg,.png" required></div><div class="col-lg-7"><div class="row g-3"><div class="col-12"><label class="form-label">Client *</label><select name="client_id" required data-smart-select data-placeholder="Rechercher un client…"><option value="">Choisir</option><?php foreach($clients as $c):?><option value="<?=(int)$c['id_client']?>"><?=oh($c['nom_client'])?></option><?php endforeach;?></select></div><div class="col-md-5"><label class="form-label">Numéro AO *</label><input class="form-control" name="num_offre" required></div><div class="col-md-7"><label class="form-label">Référence *</label><input class="form-control" name="reference_offre" required></div><div class="col-12"><label class="form-label">Titre de l’appel d’offre *</label><input class="form-control" name="titre_offre" placeholder="Ex. Fourniture et installation de groupes électrogènes" required></div><div class="col-md-6"><label class="form-label">Montant estimé (FCFA)</label><input type="number" min="0" step="0.01" class="form-control" name="montant_estime"></div><div class="col-md-6"><label class="form-label">Commercial dédié *</label><input class="form-control" name="commercial_dedie" required></div><div class="col-md-4"><label class="form-label">Date de réception *</label><input type="date" class="form-control" name="date_offre" value="<?=date('Y-m-d')?>" required></div><div class="col-md-4"><label class="form-label">Deadline *</label><input type="date" class="form-control" name="date_limite_reponse" required></div><div class="col-md-4"><label class="form-label">Date de création *</label><input type="date" class="form-control" name="date_creat_offre" value="<?=date('Y-m-d')?>" required></div><div class="col-md-6"><label class="form-label">Statut *</label><select id="statut" name="statut" required><?php foreach($statusLabels as $v=>$l):?><option value="<?=$v?>"><?=$l?></option><?php endforeach;?></select></div><div class="col-md-6" id="motifPerteZone" hidden><label class="form-label">Motif de non-attribution *</label><input class="form-control" id="motif_perte" name="motif_perte"></div></div></div><div class="col-12 text-end"><button class="btn btn-primary"><i class="fa-solid fa-floppy-disk me-2"></i>Enregistrer l’appel d’offre</button></div></div></form></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script><script>document.getElementById('statut')?.addEventListener('change',function(){const z=document.getElementById('motifPerteZone'),m=document.getElementById('motif_perte');z.hidden=this.value!=='non_remporte';m.required=this.value==='non_remporte'});<?php if($offerError):?>new bootstrap.Modal(document.getElementById('addOfferModal')).show();<?php endif;?></script></body></html>
